"""Portable paired UV error viewer; all metric targets are historical human labels."""
from pathlib import Path
import argparse,json,base64,hashlib,io,html
import numpy as np
from PIL import Image
from meat_features import write,sha
from analyze_face_v12 import analyze
NAMES={'current_reference':'线上旧五类参考','ordinary_historical':'历史普通 v9','balanced_historical':'历史均衡 v9b','guarded_v11':'历史保守 v11','ordinary_control':'匹配普通 · 原人工数据','balanced_control':'匹配均衡 · 原人工数据','ordinary_augmented':'普通 · 加入新增标注','balanced_augmented':'均衡 · 加入新增标注'}
CLASSES={1:'裸露皮肤',2:'眼睛',3:'嘴巴',5:'眉毛',6:'胡子',9:'眼影',10:'鼻子'}

def report(run):
 analysis=analyze(run);cmp=json.loads((run/'comparison.json').read_text());source=json.loads((run/'data_source.json').read_text());parent=Path(source['parent']);manifest=json.loads((run/'evaluation_manifest.json').read_text());variants=list(cmp['results']);cards=[];assets={}
 def b64(a):return base64.b64encode(np.asarray(a,dtype=np.uint8).tobytes()).decode()
 for r in manifest['rows']:
  rid=r['id'];d=run/rid;t=np.load(d/'truth.npz');rgba=np.array(Image.open(d/'skin.png').convert('RGBA'));p=parent/rid/'original_views.png'
  im=Image.open(p).convert('RGB');im.thumbnail((640,340));buf=io.BytesIO();im.save(buf,format='JPEG',quality=88);data=buf.getvalue();assets[rid]=hashlib.sha256(data).hexdigest()
  cards.append(dict(id=rid,rgba=b64(rgba),valid=b64(t['valid']),truth=b64(t['labels']),predictions={v:b64(np.load(d/(v+'.npz'))['labels']) for v in variants},metrics=analysis['cases'][rid],image='data:image/jpeg;base64,'+base64.b64encode(data).decode()))
 def pct(x):return f'{x:.1%}'
 overall=''.join('<tr><td>'+NAMES[v]+'</td>'+''.join('<td>'+x+'</td>' for x in [pct(s['macro']['iou']),pct(s['macro']['precision']),pct(s['macro']['recall']),str(s['pooled']['fp']),str(s['pooled']['fn'])])+'</tr>' for v,s in cmp['results'].items())
 rare=''
 for cls in [6,9,10]:
  for v in variants:
   m=analysis['metrics'][v][str(cls)];cells=[NAMES[v],CLASSES[cls]]
   cells+= [str(m['tp']),str(m['fp']),str(m['fn']),pct(m['precision']),pct(m['recall']),pct(m['f1']),f"{m['detected_positive_skins']}/{m['positive_skins']}",str(m['binary_parent_errors_on_positive_cells'])] if m['supported'] else ['—']*8
   rare+='<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in cells)+'</tr>'
 changes=''
 for pair,values in analysis['matched_comparisons'].items():
  for cls,m in values.items():
   delta=m['precision_recall_f1_delta'];changes+='<tr>'+''.join('<td>'+str(x)+'</td>' for x in [NAMES[pair.split('__')[0]],CLASSES[int(cls)],f"{m['delta_fp']:+d}",f"{m['delta_fn']:+d}",f'{delta[0]*100:+.1f}',f'{delta[1]*100:+.1f}',f'{delta[2]*100:+.1f}'])+'</tr>'
 payload=dict(cases=cards,names=NAMES,variants=variants,metrics=analysis['metrics']);options=''.join(f'<option value="{v}">{NAMES[v]}</option>' for v in variants)
 doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MC Meat · 新增标注重训对比</title><style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#dce6ee;background:#111924}*{box-sizing:border-box}body{margin:0}main{max-width:1500px;margin:auto;padding:30px 22px}h1{font-size:30px}h2{font-size:20px;margin:5px 0}p{line-height:1.7;color:#afc0d1}.note{padding:14px 18px;border-left:3px solid #efbc73;background:#302a21;color:#f5dfbd}.summary{display:flex;gap:14px;flex-wrap:wrap}.summary div{flex:1;background:#1d2b3c;padding:16px;border-radius:10px;min-width:180px}.summary b{font-size:28px;color:#89dfbf;display:block}table{border-collapse:collapse;width:100%;font-size:13px;margin:15px 0;background:#1a2737}th,td{text-align:left;padding:9px;border:1px solid #35495f}th{color:#9ddfc5}.scroll{overflow:auto}details{margin:18px 0}summary{cursor:pointer;padding:8px;color:#a1cff1}.controls{position:sticky;top:0;z-index:4;background:#172433f5;padding:14px;border:1px solid #43586e;border-radius:10px;display:flex;gap:10px;flex-wrap:wrap}select,input{background:#101b28;color:#e4edf4;padding:8px;border:1px solid #5c748b;border-radius:6px;font-size:14px}article{padding:22px;background:#192738;border:1px solid #364f67;border-radius:12px;margin:24px 0}.head{display:flex;gap:24px;align-items:center;flex-wrap:wrap}.head img{max-width:360px;width:100%;border-radius:6px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#111e2c;border-radius:8px;padding:14px}.panel h3{font-size:16px;min-height:32px}.uv{width:min(100%,320px);image-rendering:pixelated}.faces{width:min(100%,400px);image-rendering:pixelated;margin-left:10px}.stats{font-size:14px;color:#b5cfe4;line-height:1.6}.legend{display:flex;gap:18px;flex-wrap:wrap;padding:14px 0}.legend span{font-size:13px}.legend i{display:inline-block;width:12px;height:12px;margin-right:6px}.count{align-self:center;color:#b1d4ec;font-size:14px}[hidden]{display:none!important}footer{font-size:13px;color:#99aec2;margin:24px 0}@media(max-width:900px){.panels{grid-template-columns:1fr}.controls{position:static}.faces{margin-left:0}main{padding:15px}}
</style><main><p>MC MEAT / WEAK ANNOTATION EXPANSION / V12</p><h1>新增标注是否减少了漏检与误选？</h1><div class="summary"><div><b>169</b>固定历史人工验证样本</div><div><b>42</b>新增辅助训练样本</div><div><b>4 组 × 5 折</b>普通／均衡 × 原数据／扩充</div><div><b>200 epoch</b>固定训练长度，阈值 0.5</div></div>
<p>冻结 DINO，继续训练同一面部解码器结构。新增二分类标签权重 0.5，细类按保存的逐格置信度降权；未补细标的格子只参与二分类。1 张与历史 source 重复的新皮肤被排除。所有图示预测均为留出结果，新增助手标注不参与指标或选阈值。</p>
<p class="note">这里的“胡子／眼影／鼻子漏检”指细分类没有命中；被分到裸露皮肤的鼻子可能仍被正确选为 meat。请同时看细分类 FP/FN 和肉体二分类误选。正例只有胡子 5 张／165 格、眼影 8 张／28 格、鼻子 9 张／17 格；这是历史开发集，不是全新盲测。</p>
<details open><summary>同条件对照：加入新增标注后的变化</summary><p>下表是“加入新增标注 − 同设置原人工数据”。FP/FN 负值表示减少；精确率、召回率和 F1 为百分点变化。新四组都保持原验证折，训练时排除已知同 source 的验证对应记录。历史模型保留原结果，不能单独用于归因新增数据效果。</p><div class="scroll"><table><tr><th>匹配对照</th><th>类别</th><th>Δ误选 FP</th><th>Δ漏检 FN</th><th>Δ精确率 pp</th><th>Δ召回 pp</th><th>ΔF1 pp</th></tr>CHANGES</table></div></details>
<details open><summary>各版本 meat 二分类</summary><div class="scroll"><table><tr><th>版本</th><th>平均 IoU</th><th>平均精确率</th><th>平均召回</th><th>误选格</th><th>漏选格</th></tr>OVERALL</table></div></details>
<details><summary>胡子、眼影、鼻子详细指标</summary><div class="scroll"><table><tr><th>版本</th><th>类别</th><th>TP</th><th>误选 FP</th><th>漏检 FN</th><th>精确率</th><th>召回</th><th>F1</th><th>至少命中一格的正例皮肤</th><th>正例格的二分类错误</th></tr>RARE</table></div><p>线上旧五类参考不支持眼影、鼻子，显示“—”。线上参考使用对应历史留出权重／未见样本，训练量与新模型不同。完整类别转移和按 source 分组的探索性区间见 rare_analysis.json。</p></details>
<div class="controls"><input id="query" placeholder="图片 ID"><select id="class"><option value="6">胡子</option><option value="9">眼影</option><option value="10">鼻子</option><option value="all">所有七类</option></select><select id="scope"><option value="positive">人工标有此类</option><option value="negative">未标此类但有误选</option><option value="errors">右侧结果有错误</option><option value="all">全部案例</option></select><select id="left">OPTIONS</select><select id="right">OPTIONS</select><select id="mode"><option value="errors">逐格错误</option><option value="labels">分类覆盖</option></select><span class="count" id="count"></span></div>
<div class="legend"><span><i style="background:#3dd4a0"></i>正确命中</span><span><i style="background:#ff4761"></i>误选 FP</span><span><i style="background:#ffd15c"></i>漏检 FN</span><span>每侧：全 UV，及内层正／后面、外层正／后面放大</span></div><div id="cases"></div><footer>全量训练权重与留出权重分别保存。页面没有将训练样本拟合率当作泛化效果；新模型未替换线上预选。默认左右显示匹配均衡对照与新增标注均衡版，保留成功与退步案例。</footer></main>
<script type="application/json" id="data">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('data').textContent),E={};for(const k of ['query','class','scope','left','right','mode','count'])E[k]=document.getElementById(k);E.left.value='balanced_control';E.right.value='balanced_augmented';
function bytes(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}const colors={0:[65,70,80],1:[38,187,128],2:[0,169,232],3:[241,123,157],5:[234,154,39],6:[199,124,71],9:[183,128,237],10:[255,115,87]};
for(const c of D.cases){c.a=bytes(c.rgba);c.v=bytes(c.valid);c.t=bytes(c.truth);c.p={};for(const k of D.variants)c.p[k]=bytes(c.predictions[k]);const a=document.createElement('article');a.dataset.id=c.id;a.innerHTML='<div class="head"><img loading="lazy" src="'+c.image+'" alt="原皮肤渲染"><div><h2>'+c.id+'</h2><p>人工标注是固定评测目标。左、右均为未训练该验证皮肤的预测。</p></div></div><div class="panels">'+[0,1].map(()=>'<div class="panel"><h3></h3><div class="stats"></div><canvas class="uv" width="64" height="64"></canvas><canvas class="faces" width="32" height="8"></canvas></div>').join('')+'</div>';document.getElementById('cases').appendChild(a);c.el=a;}
function known(c,model,cl){return cl==='all'||D.metrics[model][cl].supported;}
function stat(c,model,cl){if(!known(c,model,cl))return '此模型不支持该细类';if(cl==='all'){let wrong=0;for(let i=0;i<4096;i++)if(c.v[i]&&c.p[model][i]!==c.t[i])wrong++;return '七类／其他不一致 '+wrong+' 格';}const m=c.metrics[cl][model];return '正确 TP '+m.tp+' · 误选 FP '+m.fp+' · 漏检 FN '+m.fn+' · 真值 '+m.positive_cells+' 格';}
function pixels(c,model,cl,mode){const out=new Uint8ClampedArray(16384),pred=c.p[model],supported=known(c,model,cl);for(let i=0;i<4096;i++){let color=null;const x=i%64,y=Math.floor(i/64),off=i*4;if(!c.v[i]){const g=(x+y)%2?224:240;out.set([g,g,g,255],off);continue;}if(supported){if(mode==='labels'){if(cl==='all')color=colors[pred[i]];else if(pred[i]===Number(cl))color=colors[pred[i]];}else if(cl==='all'){if(pred[i]!==c.t[i])color=c.t[i]===0?[255,71,97]:[255,209,92];else if(c.t[i]>0)color=[61,212,160];}else{const truth=c.t[i]===Number(cl),selected=pred[i]===Number(cl);if(truth&&selected)color=[61,212,160];else if(selected)color=[255,71,97];else if(truth)color=[255,209,92];}}for(let j=0;j<3;j++)out[off+j]=color?Math.round(c.a[off+j]*.25+color[j]*.75):c.a[off+j];out[off+3]=255;}return out;}
function draw(c,side,model,cl,mode){const p=c.el.querySelectorAll('.panel')[side];p.querySelector('h3').textContent=D.names[model];p.querySelector('.stats').textContent=stat(c,model,cl);const uv=p.querySelector('.uv'),ctx=uv.getContext('2d');const img=ctx.createImageData(64,64);img.data.set(pixels(c,model,cl,mode));ctx.putImageData(img,0,0);const z=p.querySelector('.faces').getContext('2d');z.imageSmoothingEnabled=false;for(const[j,u]of[8,24,40,56].entries())z.drawImage(uv,u,8,8,8,j*8,0,8,8);}
function metric(c,model,cl){return c.metrics[cl][model]||{tp:0,fp:0,fn:0,positive_cells:Array.from(c.t).filter(x=>x===Number(cl)).length};}
function update(){let n=0;const cl=E.class.value;for(const c of D.cases){const m=cl==='all'?null:metric(c,E.right.value,cl);let yes=c.id.toLowerCase().includes(E.query.value.toLowerCase());if(cl!=='all'){if(E.scope.value==='positive')yes=yes&&m.positive_cells>0;if(E.scope.value==='negative')yes=yes&&m.positive_cells===0&&m.fp>0;if(E.scope.value==='errors')yes=yes&&m.fp+m.fn>0;}c.el.hidden=!yes;if(yes){n++;draw(c,0,E.left.value,cl,E.mode.value);draw(c,1,E.right.value,cl,E.mode.value);}}E.count.textContent='显示 '+n+' / '+D.cases.length+' 张';}for(const k of ['query','class','scope','left','right','mode'])E[k].addEventListener('input',update);update();
</script></html>'''
 doc=doc.replace('CHANGES',changes).replace('OVERALL',overall).replace('RARE',rare).replace('OPTIONS',options).replace('PAYLOAD',json.dumps(payload,ensure_ascii=False,separators=(',',':')))
 (run/'review_report_portable.html').write_text(doc);write(run/'report_images.json',assets);write(run/'report_provenance.json',dict(report_sha256=sha(run/'review_report_portable.html'),code_sha256=sha(Path(__file__)),comparison_sha256=sha(run/'comparison.json'),human_cases=169,embedded_renders=169))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);a=p.parse_args();report(a.run)
